/* Squad, tactics and market */
.content-row{display:flex;gap:15px;align-items:flex-start}.main-column{flex:1;min-width:0}.side-column{width:300px;flex-shrink:0}.panel{padding:18px}.toolbar{display:flex;gap:9px;align-items:center;margin-bottom:14px}.searchbox{height:36px;border:1px solid var(--line);border-radius:8px;display:flex;align-items:center;gap:7px;padding:0 10px;background:#fff;flex:1;color:#84918c}.searchbox input{border:0;outline:0;font:inherit;width:100%;font-size:10px;color:var(--ink)}.filter-select{height:36px;border:1px solid var(--line);border-radius:8px;background:#fff;padding:0 11px;color:#596763;font-size:10px}.player-table{width:100%;border-collapse:collapse}.player-table th{text-align:left;padding:10px 8px;color:#98a29e;font-size:8px;letter-spacing:.7px;text-transform:uppercase;border-bottom:1px solid var(--line)}.player-table td{padding:11px 8px;border-bottom:1px solid #f0f2ef;font-size:10px;color:#5b6965;white-space:nowrap}.player-table tr:last-child td{border-bottom:0}.player-name{display:flex;align-items:center;gap:9px}.player-avatar{height:31px;width:31px;background:#edf2e8;border-radius:9px;display:grid;place-items:center;color:#60764f;font-size:10px;font-weight:800}.player-name b{display:block;color:#34433f;font-size:10px}.player-name small{display:block;color:#9aa49f;font-size:8px;margin-top:3px}.pos-tag{border-radius:5px;padding:4px 6px;background:#f0f4ee;color:#687b61;font-size:8px;font-weight:800}.rating{font:700 11px 'Space Grotesk';color:#31443b}.condition{display:flex;align-items:center;gap:6px}.condition-bar{width:39px;height:4px;background:#ecf0ea;border-radius:4px;overflow:hidden}.condition-bar i{display:block;height:100%;background:#7ac793;border-radius:4px}.player-action{border:0;background:#f2f6ef;color:#42734d;border-radius:6px;padding:6px 8px;font-size:9px;font-weight:700}.player-table tbody tr{cursor:pointer}.player-table tbody tr:hover{background:#fafbf8}.squad-summary{display:flex;gap:10px;margin-bottom:14px}.summary-chip{background:#fff;border:1px solid var(--line);border-radius:9px;padding:9px 13px;color:#687571;font-size:9px}.summary-chip b{font:700 15px 'Space Grotesk';color:#263b32;margin-right:5px}.tactic-layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(240px,.75fr);gap:15px}.pitch-panel{padding:14px}.pitch{height:490px;max-height:58vh;min-height:390px;position:relative;overflow:hidden;border-radius:12px;background:repeating-linear-gradient(0deg,#267e50 0,#267e50 52px,#2c8958 52px,#2c8958 104px);border:4px solid #fff}.pitch:before{content:'';position:absolute;inset:10px;border:1px solid #ffffff99;border-radius:2px}.pitch-midline{position:absolute;top:50%;left:10px;right:10px;border-top:1px solid #ffffff99}.pitch-circle{position:absolute;width:100px;height:100px;border:1px solid #ffffff99;border-radius:50%;left:50%;top:50%;transform:translate(-50%,-50%)}.box-area{position:absolute;width:45%;height:16%;left:27.5%;border:1px solid #ffffff99}.box-area.top{top:10px;border-top:0}.box-area.bottom{bottom:10px;border-bottom:0}.goal-area{position:absolute;width:24%;height:7%;left:38%;border:1px solid #ffffff99}.goal-area.top{top:10px;border-top:0}.goal-area.bottom{bottom:10px;border-bottom:0}.player-token{position:absolute;transform:translate(-50%,-50%);display:flex;flex-direction:column;align-items:center;gap:3px;color:white;font-size:8px;font-weight:700;text-shadow:0 1px 3px #153d2a;z-index:2;cursor:pointer}.token-shirt{height:24px;width:24px;border-radius:8px;background:#d9f36a;color:#153426;display:grid;place-items:center;font-size:8px;text-shadow:none;box-shadow:0 2px 6px #143c2e55;border:1px solid #f4ffc5}.pitch-header{display:flex;align-items:center;justify-content:space-between;margin:1px 2px 11px}.tactic-side{display:grid;gap:14px}.select-label{display:block;color:#8b9892;font-size:9px;text-transform:uppercase;letter-spacing:.8px;font-weight:800;margin:15px 0 7px}.select-control{width:100%;border:1px solid var(--line);border-radius:8px;padding:10px;background:#fff;color:#42534d;font:600 10px 'DM Sans'}.tactic-stat{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #f0f2ef;font-size:10px;color:#75827d}.tactic-stat b{color:#34453d}.morale-bar{height:6px;background:#eef1ec;border-radius:10px;margin-top:7px}.morale-bar i{display:block;height:100%;width:77%;background:#83c97e;border-radius:10px}.recruit-card{display:flex;align-items:center;gap:10px;padding:12px 0;border-bottom:1px solid #eff1ee}.recruit-card:last-child{border-bottom:0}.recruit-info{flex:1}.recruit-info b{display:block;font-size:10px}.recruit-info span{font-size:9px;color:#8b9793;display:block;margin-top:4px}.recruit-price{font-size:9px;font-weight:800;color:#378053}.transfer-hero{background:#e8f4dc;border-radius:14px;padding:18px;margin-bottom:14px;display:flex;justify-content:space-between;align-items:center}.transfer-hero h3{font:700 16px 'Space Grotesk';margin:7px 0 4px}.transfer-hero p{font-size:10px;color:#73816e;margin:0}.market-balance{font:700 18px 'Space Grotesk';color:#216e4a}.market-balance small{font:600 8px 'DM Sans';display:block;color:#758276;text-align:right;margin-bottom:4px;letter-spacing:.7px}.empty-state{text-align:center;padding:35px;color:#87938e;font-size:11px}
/* Modal and match presentation */
.modal-backdrop{position:fixed;inset:0;background:#0d1919b8;z-index:10;display:grid;place-items:center;padding:18px;backdrop-filter:blur(4px)}.modal{background:#fff;border-radius:18px;width:min(470px,100%);box-shadow:0 25px 80px #101c1b50;overflow:hidden;animation:pop .18s ease-out}.modal-top{padding:19px 21px 12px;display:flex;justify-content:space-between;align-items:flex-start}.modal-top h2{font:700 19px 'Space Grotesk';margin:6px 0 0}.close-modal{width:30px;height:30px;border:0;border-radius:8px;background:#f1f3ef;color:#66736e;font-size:17px}.modal-content{padding:0 21px 20px}.modal-actions{padding:13px 21px 19px;display:flex;justify-content:flex-end;gap:8px}.player-profile{display:flex;align-items:center;gap:14px;padding:8px 0 15px}.profile-avatar{width:61px;height:61px;border-radius:16px;background:#e8f1df;color:#58714a;display:grid;place-items:center;font:700 19px 'Space Grotesk'}.profile-info b{font:700 17px 'Space Grotesk';display:block}.profile-info span{font-size:10px;color:#7e8a85}.profile-rating{margin-left:auto;font:700 24px 'Space Grotesk';color:#267448}.attribute{display:grid;grid-template-columns:74px 1fr 24px;align-items:center;gap:9px;margin:9px 0;font-size:9px;color:#74817b}.attribute-bar{height:5px;border-radius:5px;background:#edf0eb}.attribute-bar i{display:block;height:100%;background:#70bd83;border-radius:5px}.attribute b{text-align:right;color:#3e5048}.match-banner{background:var(--navy);color:#fff;padding:20px;text-align:center}.match-banner .eyebrow{color:#8fa69b}.match-score{display:flex;align-items:center;justify-content:center;gap:24px;margin:12px 0}.match-team{font-size:10px;font-weight:700;width:90px}.match-team b{font:700 23px 'Space Grotesk';color:var(--lime);display:block;margin-bottom:4px}.score{font:700 32px 'Space Grotesk';letter-spacing:1px}.match-events{padding:11px 0;max-height:160px;overflow:auto}.event-line{display:flex;justify-content:space-between;padding:8px 3px;border-bottom:1px solid #eff1ee;font-size:10px;color:#68746f}.event-line b{color:#33473c}.toast{position:fixed;bottom:25px;left:50%;transform:translate(-50%,20px);background:#152522;color:white;padding:11px 16px;border-radius:9px;font-size:11px;font-weight:600;opacity:0;pointer-events:none;transition:.22s;z-index:20;box-shadow:var(--shadow)}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes pop{from{opacity:0;transform:translateY(8px) scale(.98)}to{opacity:1;transform:none}}

@media(max-width:1050px){.sidebar{width:205px}.main-area{margin-left:205px;width:calc(100% - 205px)}.content-wrap{padding:24px}.topbar{padding:0 24px}.side-column{width:260px}.dashboard-grid{grid-template-columns:1fr 300px}.tactic-layout{grid-template-columns:1fr 250px}}
@media(max-width:760px){body{font-size:13px}.sidebar{display:none}.main-area{margin:0;width:100%;padding-bottom:72px}.topbar{height:56px;padding:0 16px}.mobile-brand{display:flex;align-items:center;gap:8px;font:700 14px 'Space Grotesk';letter-spacing:1px}.mobile-brand .brand-mark{height:29px;width:30px;font-size:13px;border-radius:8px}.breadcrumb{display:none}.top-actions{gap:9px}.top-date{font-size:9px}.top-date .calendar-icon{display:none}.manager-chip{padding:3px;background:transparent}.manager-chip>span:not(.manager-avatar){display:none}.icon-button{width:30px;height:30px}.content-wrap{padding:19px 14px 28px}.page-heading{align-items:flex-start;margin-bottom:16px}.page-heading h1{font-size:23px}.page-heading p{font-size:10px;max-width:250px;line-height:1.5}.page-heading>.btn{padding:10px;font-size:10px;white-space:nowrap;margin-top:8px}.dashboard-grid{grid-template-columns:1fr;gap:11px}.hero-card{min-height:218px;padding:19px}.hero-card h2{font-size:20px;max-width:230px}.hero-card p{max-width:240px;font-size:10px}.hero-card .btn{right:17px;bottom:17px;padding:10px}.next-match{margin-top:15px}.hero-spark{right:9px;top:15px}.fixture-card{padding:16px}.stats-strip{grid-column:auto;grid-template-columns:repeat(2,1fr);gap:8px}.stat-card{min-height:78px;padding:12px}.stat-value{font-size:19px}.stat-label{font-size:8px}.stat-symbol{right:10px;top:11px;width:26px;height:26px}.lower-grid{grid-template-columns:1fr;gap:11px;margin-top:11px}.table-panel,.form-panel{padding:15px}.mobile-nav{position:fixed;inset:auto 0 0;z-index:6;height:65px;padding:6px 6px max(6px,env(safe-area-inset-bottom));display:flex;justify-content:space-around;align-items:center;background:#fff;border-top:1px solid var(--line);box-shadow:0 -6px 18px #172a2010}.mobile-nav button{flex:1;height:49px;display:grid;align-content:center;justify-items:center;gap:3px;background:none;border:0;color:#8a9691;font-size:8px;font-weight:700}.mobile-nav button span{font-size:17px}.mobile-nav button.active{color:#188353}.fixture-teams .team{width:90px}.content-row{display:block}.side-column{width:auto;margin-top:11px}.panel{padding:14px}.toolbar{flex-wrap:wrap}.searchbox{flex-basis:100%}.filter-select{flex:1}.player-table th:nth-child(4),.player-table td:nth-child(4),.player-table th:nth-child(5),.player-table td:nth-child(5){display:none}.player-table td{padding:10px 5px}.player-table th{padding:9px 5px}.player-table td:nth-child(2){font-size:9px}.player-name{gap:6px}.player-avatar{height:28px;width:28px}.squad-summary{overflow:auto}.summary-chip{white-space:nowrap;padding:8px}.tactic-layout{grid-template-columns:1fr}.pitch-panel{padding:9px}.pitch{height:440px;min-height:380px;max-height:none}.tactic-side{grid-template-columns:1fr 1fr}.tactic-side>.panel:first-child{grid-column:1/-1}.tactic-side .panel{padding:13px}.transfer-hero{padding:14px}.transfer-hero h3{font-size:14px}.transfer-hero .btn{font-size:9px;padding:8px}.modal-backdrop{padding:12px}.modal{max-height:90vh;overflow:auto}.toast{bottom:79px;max-width:calc(100% - 28px);width:max-content}.manager-chip .manager-avatar{height:29px;width:29px}}
@media(max-width:380px){.content-wrap{padding-left:10px;padding-right:10px}.hero-card h2{max-width:190px}.hero-card p{max-width:200px}.hero-card .btn{font-size:9px;padding:9px}.team{width:70px!important}.tactic-side{grid-template-columns:1fr}.tactic-side>.panel:first-child{grid-column:auto}.pitch{height:390px}}

