const opponents = ['Ferroviário AC','União de Araraquara','EC Primavera','Nacional de Muriaé','Rio Branco FC','São Bento','Grêmio Prudente','Monte Azul','Portuguesa Santista','XV de Jaú'];
const recruits = [
 {id:'r1',name:'Bruno Cavalcanti',pos:'ZAG',age:24,ovr:72,value:980000,wage:11200,attrs:{Marcação:74,Desarme:73,Força:72,Passe:65}},
