const defaultState = {day:7,month:4,year:2025,players:initialPlayers,money:2450000,points:8,wins:2,draws:2,losses:1,played:5,goalsFor:7,goalsAgainst:5,matchNo:6,formation:'4-3-3',mentality:'Equilibrada',training:'Recuperação',lastResult:'V 2–1', history:[{opponent:'São Bento',result:'2–1',kind:'win'},{opponent:'Portuguesa Santista',result:'1–1',kind:'draw'},{opponent:'XV de Jaú',result:'0–1',kind:'loss'},{opponent:'Nacional de Muriaé',result:'2–0',kind:'win'},{opponent:'Grêmio Prudente',result:'1–1',kind:'draw'}], standings:[{name:'União de Araraquara',p:11,gp:5},{name:'Atlético do Vale',p:8,gp:5},{name:'Ferroviário AC',p:8,gp:5},{name:'São Bento',p:7,gp:5},{name:'EC Primavera',p:6,gp:5},{name:'XV de Jaú',p:5,gp:5}],playedToday:false,roundSeed:0,clubName:'Atlético do Vale'};
function loadState(){try{const saved=JSON.parse(localStorage.getItem('onze-save'));if(saved)return {...structuredClone(defaultState),...saved,players:saved.players||structuredClone(initialPlayers)}}catch(e){}return structuredClone(defaultState)}
let state=loadState();let activeView='inicio';let activeFilter='TODOS';let searchQuery='';let toastTimer;
const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n);
const shortMoney=n=>n>=1000000?'R$ '+(n/1000000).toFixed(2).replace('.',',')+' mi':'R$ '+Math.round(n/1000)+' mil';
const initials=name=>name.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const dateObj=()=>new Date(state.year,state.month-1,state.day);
const formattedDate=()=>new Intl.DateTimeFormat('pt-BR',{weekday:'short',day:'2-digit',month:'short',year:'numeric'}).format(dateObj()).replace('.','').toUpperCase();
function save(){localStorage.setItem('onze-save',JSON.stringify(state));updateHeader()}
function showToast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function updateHeader(){document.getElementById('top-date').textContent=formattedDate();document.getElementById('squad-count').textContent=state.players.length}
function setView(view){activeView=view;document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id==='view-'+view));document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));const titles={inicio:'VISÃO GERAL',elenco:'ELENCO',taticas:'TÁTICAS',mercado:'MERCADO'};document.getElementById('crumb-title').textContent=titles[view];renderView()}
document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>setView(el.dataset.view)));
function renderView(){if(activeView==='inicio')renderHome();if(activeView==='elenco')renderSquad();if(activeView==='taticas')renderTactics();if(activeView==='mercado')renderMarket()}
function matchOpponent(){return opponents[(state.matchNo-1)%opponents.length]}
function nextMatchDate(){let d=dateObj();d.setDate(d.getDate()+Math.max(0,7-((state.day-1)%7)));return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long'}).format(d)}
function averageRating(){return (state.players.slice(0,11).reduce((a,p)=>a+p.ovr,0)/11).toFixed(1)}
function renderHome(){
 const view=document.getElementById('view-inicio');const op=matchOpponent();const matchReady=state.day>=7&& !state.playedToday;
 const standings=[...state.standings].sort((a,b)=>b.p-a.p).slice(0,5);
 const playedRows=state.history.slice(0,4).map(h=>`<div class="form-row"><div class="form-mark ${h.kind}">${h.kind==='win'?'V':h.kind==='draw'?'E':'D'}</div><div><b>${h.opponent}</b><span>${h.kind==='win'?'Vitória':h.kind==='draw'?'Empate':'Derrota'} · Série C</span></div><div class="form-score">${h.result}</div></div>`).join('');
 view.innerHTML=`<div class="page-heading"><div><div class="eyebrow">SEGUNDA-FEIRA, ${state.day} DE ABRIL</div><h1>Bom dia, Caio 👋</h1><p>O treino de hoje está pronto. Vamos preparar o time?</p></div><button class="btn btn-outline" onclick="advanceDay()"><span class="icon">◷</span> Avançar dia</button></div>
 <div class="grid dashboard-grid"><section class="hero-card"><div class="eyebrow">${matchReady?'DIA DE JOGO · RODADA '+state.matchNo:'PRÓXIMO DESAFIO · RODADA '+state.matchNo}</div><h2>${matchReady?'A hora da verdade.':'A semana é nossa.'}</h2><p>${matchReady?'O elenco está pronto para entrar em campo. Escolha sua estratégia e busque os três pontos.':'Trabalhe o entrosamento e cuide da condição física antes do próximo compromisso.'}</p><div class="next-match"><div class="match-badge">${op.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div class="match-meta"><b>Atlético do Vale <span style="color:#8fa39a;font-weight:400">×</span> ${op}</b><span>${matchReady?'Hoje':'Domingo, '+nextMatchDate()} · 16:00 · Estádio do Vale</span></div></div><div class="hero-spark">✳</div><button class="btn btn-lime" onclick="${matchReady?'playMatch()':'openTraining()'}">${matchReady?'⚽  Jogar partida':'＋  Preparar equipe'}</button></section>
 <section class="fixture-card"><div class="section-top"><h3 class="section-title">Próxima partida</h3><span class="eyebrow">SÉRIE C</span></div><div class="fixture-date">${matchReady?'HOJE · 16:00':'DOMINGO, '+nextMatchDate()+' · 16:00'}</div><div class="fixture-teams"><div class="team"><div class="team-crest">AV</div><span>Atlético do Vale</span></div><div class="versus">VS</div><div class="team opponent"><div class="team-crest">${op.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><span>${op}</span></div></div><div class="fixture-footer"><span>Estádio do Vale</span><b>Rodada ${state.matchNo}</b></div></section>
 <div class="grid stats-strip"><div class="stat-card"><span class="stat-label">Posição na liga</span><div class="stat-value">2º <small style="font:500 10px 'DM Sans';color:#84908d">/ 10</small></div><div class="stat-foot good">▲ Na zona de classificação</div><span class="stat-symbol">♜</span></div><div class="stat-card"><span class="stat-label">Pontos</span><div class="stat-value">${state.points}</div><div class="stat-foot">${state.wins}V · ${state.draws}E · ${state.losses}D</div><span class="stat-symbol">✦</span></div><div class="stat-card"><span class="stat-label">Saldo de gols</span><div class="stat-value">${state.goalsFor-state.goalsAgainst>0?'+':''}${state.goalsFor-state.goalsAgainst}</div><div class="stat-foot">${state.goalsFor} marcados · ${state.goalsAgainst} sofridos</div><span class="stat-symbol">⚽</span></div><div class="stat-card"><span class="stat-label">Caixa do clube</span><div class="stat-value" style="font-size:19px">${shortMoney(state.money)}</div><div class="stat-foot">Folha semanal ${shortMoney(state.players.reduce((a,p)=>a+p.wage,0))}</div><span class="stat-symbol">＄</span></div></div></div>
 <div class="grid lower-grid"><section class="panel table-panel"><div class="panel-heading"><h3 class="section-title">Classificação · Grupo 2</h3><button class="subtle-link" onclick="showToast('Classificação atualizada após cada rodada')">Tabela completa ↗</button></div><table class="standing-table"><thead><tr><th>#</th><th>Clube</th><th>Pts</th><th>J</th><th>SG</th></tr></thead><tbody>${standings.map((row,i)=>`<tr class="${row.name==='Atlético do Vale'?'highlight':''}"><td>${i+1}</td><td>${row.name}</td><td>${row.p}</td><td>${row.gp}</td><td>${row.name==='Atlético do Vale'?state.goalsFor-state.goalsAgainst:i===0?5:i===2?2:0}</td></tr>`).join('')}</tbody></table></section><section class="panel form-panel"><div class="panel-heading"><h3 class="section-title">Últimos resultados</h3><span class="eyebrow">FORMA</span></div><div class="form-list">${playedRows}</div><div class="form-summary"><i></i><i></i><i></i><i></i><i></i></div></section></div>`;
}

