'use strict';

const SAVE_KEY = 'onze-save';
const CLUB = 'Atlético do Vale';
const teams = ['Ferroviária','Ypiranga-RS','São Bernardo','Londrina','CSA','Figueirense','Botafogo-PB','Confiança','Caxias','Tombense','Remo','ABC','Volta Redonda','Aparecidense','Náutico','Sampaio Corrêa','Floresta','Retrô','Brusque'];
const names = [
  ['Rafael Nunes','GOL',67],['João Victor','ZAG',66],['Davi Rocha','ZAG',64],['Luan Costa','LD',65],['Mateus Ribeiro','LE',63],['Caio Mendes','VOL',67],['Bruno Almeida','MC',68],['Igor Santos','MEI',69],['Pedro Henrique','PD',70],['Lucas Ferreira','PE',67],['André Luiz','CA',71],['Enzo Martins','GOL',60],['Samuel Barros','ZAG',61],['Felipe Araújo','LD',59],['Murilo Dias','VOL',62],['Thiago Lima','MC',61],['Gabriel Souza','MEI',64],['Vitor Hugo','PE',62],['Renan Oliveira','CA',63],['Diego Carvalho','PD',60]
];
const attrNames = ['Passe','Finalização','Marcação','Resistência'];
function makePlayers(){return names.map(([name,pos,ovr],i)=>({id:i+1,name,pos,ovr,age:19+(i*7%15),condition:82+(i*11%18),morale:68+(i*9%26),wage:Math.round((ovr-45)*1750),value:(ovr-45)*38000,attrs:{Passe:Math.max(45,ovr+(i%5)-2),Finalização:Math.max(42,ovr+(i%7)-5),Marcação:Math.max(44,ovr+(i%3)-1),Resistência:Math.max(50,ovr+(i%6)-2)}}));}
function freshState(){return {day:7,month:4,year:2025,money:1850000,players:makePlayers(),points:0,wins:0,draws:0,losses:0,played:0,goalsFor:0,goalsAgainst:0,matchNo:1,lastResult:'—',history:[],playedToday:false,trainingApplied:false,training:'Posse de bola',mentality:'Equilibrada',formation:'4-3-3',standings:[{name:CLUB,p:0,gp:0},...teams.map((name,i)=>({name,p:Math.max(0,14-i),gp:0}))]};}
let state;
try { const stored=JSON.parse(localStorage.getItem(SAVE_KEY)); state=stored&&Array.isArray(stored.players)&&stored.players.length>=11?{...freshState(),...stored}:freshState(); } catch { state=freshState(); }

const $ = (selector,root=document)=>root.querySelector(selector);
const $$ = (selector,root=document)=>[...root.querySelectorAll(selector)];
const money = n => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n);
const dateObj = () => new Date(state.year,state.month-1,state.day,12);
const formatDate = d => new Intl.DateTimeFormat('pt-BR',{weekday:'short',day:'2-digit',month:'short'}).format(d).replace('.','').toUpperCase();
function save(){localStorage.setItem(SAVE_KEY,JSON.stringify(state));updateHeader();}
function showToast(message){const toast=$('#toast');toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2600);}
function openModal(title,body,actions=''){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true"><header><h2>${title}</h2><button class="icon-button" onclick="closeModal()" aria-label="Fechar">×</button></header><div class="modal-body">${body}</div><footer>${actions||'<button class="btn btn-primary" onclick="closeModal()">Fechar</button>'}</footer></section></div>`;}
function closeModal(){$('#modal-root').innerHTML='';}
function updateHeader(){$('#top-date').textContent=formatDate(dateObj());$('#squad-count').textContent=state.players.length;}
let currentView='inicio';
function navigate(view){currentView=view;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));const labels={inicio:'VISÃO GERAL',elenco:'ELENCO',taticas:'TÁTICAS',mercado:'MERCADO'};$('#crumb-title').textContent=labels[view];renderView();}
function renderView(){const renderers={inicio:renderHome,elenco:renderSquad,taticas:renderTactics,mercado:renderMarket};(renderers[currentView]||renderHome)();updateHeader();}

