function renderView(){const renderers={inicio:renderHome,elenco:renderSquad,taticas:renderTactics,mercado:renderMarket};(renderers[currentView]||renderHome)();updateHeader();}
function opponentForRound(){return teams[(state.matchNo-1)%teams.length];}
function nextSunday(){const d=dateObj();const days=(7-d.getDay())%7;d.setDate(d.getDate()+days);return d;}
function playerCard(p,index){return `<div class="player-row"><span class="player-number">${String(index+1).padStart(2,'0')}</span><span class="player-avatar ${p.pos==='GOL'?'keeper':''}">${p.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><div class="player-info"><b>${p.name}</b><small>${p.pos} · ${p.age} anos</small></div><div class="player-condition"><b>${p.condition}%</b><small>condição</small><span><i style="width:${p.condition}%"></i></span></div><b class="ovr">${p.ovr}</b><button class="text-action" onclick="playerDetails(${p.id})">›</button></div>`;}
function playerDetails(id){const p=state.players.find(x=>x.id===id);openModal(p.name,`<div class="player-detail"><div class="detail-rating">${p.ovr}<small>GER</small></div><div><b>${p.pos} · ${p.age} anos</b><p>Condição ${p.condition}% · Moral ${p.morale}%</p><p>Salário semanal: ${money(p.wage)}</p><p>Valor estimado: ${money(p.value)}</p></div></div>${Object.entries(p.attrs).map(([k,v])=>`<div class="attribute"><span>${k}</span><b>${v}</b><i><em style="width:${v}%"></em></i></div>`).join('')}`,`<button class="btn btn-secondary" onclick="closeModal()">Fechar</button><button class="btn btn-primary" onclick="applyTraining(${p.id});closeModal()">Treinar jogador</button>`)}
function renderHome(){const own=state.standings.find(x=>x.name===CLUB);const rank=state.standings.indexOf(own)+1;const opponent=opponentForRound();const sunday=dateObj().getDay()===0;const action=sunday&&!state.playedToday?`<button class="btn btn-lime" onclick="playMatch()">JOGAR PARTIDA <span>→</span></button>`:`<button class="btn btn-lime" onclick="advanceDay()">AVANÇAR DIA <span>→</span></button>`;$('#view-inicio').innerHTML=`<div class="page-heading"><div><div class="eyebrow">TEMPORADA 2025 <span class="dot-sep">•</span> SÉRIE C</div><h1>Bom dia, Caio <span>👋</span></h1><p>Seu próximo desafio começa com as decisões de hoje.</p></div><button class="btn btn-secondary" onclick="openModal('Salvar carreira','Seu progresso é salvo automaticamente neste dispositivo.','<button class=\'btn btn-primary\' onclick=\'closeModal()\'>Entendi</button>')">☁ <span>Carreira salva</span></button></div>
<div class="dashboard-grid"><section class="hero-card"><div class="hero-copy"><span class="hero-kicker"><i></i> PRÓXIMO DESAFIO</span><h2>${sunday&&!state.playedToday?'Dia de jogo. Vamos, Vale!':'O trabalho de hoje constrói a vitória de amanhã.'}</h2><p>${sunday&&!state.playedToday?'A torcida está pronta. Defina sua estratégia e entre em campo.':'Prepare o elenco para a próxima rodada da Série C.'}</p>${action}</div><div class="hero-ball">⚽</div><div class="hero-spark">✳</div></section>
<section class="fixture-card"><div class="panel-top"><span>PRÓXIMA PARTIDA</span><span class="status-pill">${state.playedToday?'ENCERRADA':'RODADA '+state.matchNo}</span></div><div class="fixture-date">${formatDate(nextSunday())} <span>· 16:00</span></div><div class="fixture-teams"><div class="team"><div class="team-crest">AV</div><b>Atlético<br>do Vale</b></div><div class="versus">${state.playedToday?state.lastResult:'VS'}</div><div class="team"><div class="team-crest opponent-crest">${opponent.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><b>${opponent}</b></div></div><div class="fixture-venue">⌖ &nbsp; Estádio Municipal · Casa</div><button class="fixture-link" onclick="navigate('taticas')">Preparar equipe <span>→</span></button></section>
<div class="stats-strip"><article class="stat-card"><span class="stat-label">POSIÇÃO NA LIGA</span><span class="stat-symbol">⌖</span><b class="stat-value">${rank}<small>º</small></b><span class="stat-foot">de 20 clubes</span></article><article class="stat-card"><span class="stat-label">PONTOS</span><span class="stat-symbol">♧</span><b class="stat-value">${state.points}</b><span class="stat-foot">${state.played} jogos disputados</span></article><article class="stat-card"><span class="stat-label">CAIXA DO CLUBE</span><span class="stat-symbol">＄</span><b class="stat-value">${money(state.money)}</b><span class="stat-foot ${state.money<0?'negative':''}">Folha: ${money(state.players.reduce((a,p)=>a+p.wage,0))}/sem</span></article><article class="stat-card"><span class="stat-label">CAMPANHA</span><span class="stat-symbol">▥</span><b class="stat-value form-value">${state.wins}V <i>${state.draws}E</i> <em>${state.losses}D</em></b><span class="stat-foot">${state.goalsFor} gols marcados</span></article></div></div>
<div class="lower-grid"><section class="panel table-panel"><div class="section-title"><div><h3>Tabela da Série C</h3><p>Grupo A · Temporada 2025</p></div><button class="text-action" onclick="showToast('Tabela atualizada após cada rodada')">•••</button></div><div class="table-head"><span>#</span><span>CLUBE</span><span>J</span><span>PTS</span></div><div class="standings">${state.standings.slice(0,6).map((t,i)=>`<div class="table-row ${t.name===CLUB?'own-row':''}"><span class="rank-cell">${i+1}</span><b>${t.name}</b><span>${t.gp}</span><strong>${t.p}</strong></div>`).join('')}</div><button class="table-more" onclick="openModal('Classificação completa',standingsMarkup())">Ver classificação completa <span>→</span></button></section>
<section class="panel form-panel"><div class="section-title"><div><h3>Últimos resultados</h3><p>A jornada do Atlético</p></div><span class="form-badge">${state.played} J</span></div>${state.history.length?`<div class="history-list">${state.history.slice(0,4).map(h=>`<div class="history-row"><span class="result-mark ${h.kind}">${h.kind==='win'?'V':h.kind==='draw'?'E':'D'}</span><span>Atlético do Vale <small>vs. ${h.opponent}</small></span><b>${h.result}</b></div>`).join('')}</div>`:`<div class="empty-state"><span>◷</span><b>Sua temporada começa agora</b><p>Os resultados aparecerão aqui após a primeira partida.</p></div>`}<button class="table-more" onclick="navigate('elenco')">Ver meu elenco <span>→</span></button></section></div>`;}
function standingsMarkup(){return `<div class="table-head"><span>#</span><span>CLUBE</span><span>J</span><span>PTS</span></div>${state.standings.map((t,i)=>`<div class="table-row ${t.name===CLUB?'own-row':''}"><span class="rank-cell">${i+1}</span><b>${t.name}</b><span>${t.gp}</span><strong>${t.p}</strong></div>`).join('')}`;}

