function standingsMarkup(){return `<div class="table-head"><span>#</span><span>CLUBE</span><span>J</span><span>PTS</span></div>${state.standings.map((t,i)=>`<div class="table-row ${t.name===CLUB?'own-row':''}"><span class="rank-cell">${i+1}</span><b>${t.name}</b><span>${t.gp}</span><strong>${t.p}</strong></div>`).join('')}`;}
function renderSquad(){const starters=state.players.slice(0,11),reserves=state.players.slice(11);$('#view-elenco').innerHTML=`<div class="page-heading"><div><div class="eyebrow">ATLÉTICO DO VALE · TEMPORADA 2025</div><h1>Nosso elenco</h1><p>Conheça os atletas e cuide da condição física do grupo.</p></div><button class="btn btn-primary" onclick="openModal('Treino do elenco',trainingMarkup())">▣ <span>Treino da equipe</span></button></div><div class="squad-summary"><div><span>ELENCO</span><b>${state.players.length}<small> jogadores</small></b></div><div><span>IDADE MÉDIA</span><b>${(state.players.reduce((a,p)=>a+p.age,0)/state.players.length).toFixed(1)}<small> anos</small></b></div><div><span>FOLHA SEMANAL</span><b>${money(state.players.reduce((a,p)=>a+p.wage,0))}</b></div><div><span>OVR MÉDIO</span><b>${Math.round(state.players.reduce((a,p)=>a+p.ovr,0)/state.players.length)}</b></div></div><section class="panel roster-panel"><div class="section-title"><div><h3>Time titular</h3><p>${state.formation} · onze inicial</p></div><span class="form-badge">${starters.length} atletas</span></div><div class="roster-list">${starters.map(playerCard).join('')}</div></section><section class="panel roster-panel reserve-panel"><div class="section-title"><div><h3>Banco de reservas</h3><p>Opções para mudar o jogo</p></div><span class="form-badge">${reserves.length} atletas</span></div><div class="roster-list">${reserves.map((p,i)=>playerCard(p,i+11)).join('')}</div></section>`;}
function trainingMarkup(){return `<p class="modal-intro">Uma sessão de treino por dia. Escolha um foco para o elenco titular.</p><div class="training-options">${['Posse de bola','Finalização','Defesa','Condicionamento','Recuperação'].map(t=>`<button class="training-option ${state.training===t?'selected':''}" onclick="state.training='${t}';$$('.training-option').forEach(x=>x.classList.remove('selected'));this.classList.add('selected')"><b>${t}</b><small>${t==='Recuperação'?'Recupera condição física':t==='Condicionamento'?'Melhora o preparo físico':'Desenvolve atributos do grupo'}</small></button>`).join('')}</div><p class="modal-note">${state.trainingApplied?'Treino já realizado hoje. Avance o dia para treinar novamente.':'O treino pode aumentar atributos, mas também exige energia dos atletas.'}</p>`,`<button class="btn btn-secondary" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" ${state.trainingApplied?'disabled':''} onclick="applyTraining();closeModal()">Confirmar treino</button>`;}
function renderTactics(){$('#view-taticas').innerHTML=`<div class="page-heading"><div><div class="eyebrow">COMISSÃO TÉCNICA · PLANO DE JOGO</div><h1>Táticas e estratégia</h1><p>Monte o plano para o próximo desafio do Atlético.</p></div><button class="btn btn-primary" onclick="save();showToast('Estratégia salva com sucesso.')">✓ <span>Salvar táticas</span></button></div><div class="tactic-layout"><section class="panel pitch-panel"><div class="section-title"><div><h3>Formação titular</h3><p>Arranjo tático em campo</p></div><select class="select-control" onchange="state.formation=this.value;renderTactics();save()">${['4-3-3','4-4-2','3-5-2'].map(f=>`<option ${state.formation===f?'selected':''}>${f}</option>`).join('')}</select></div><div class="pitch"><div class="pitch-lines"></div><div class="formation-slots">${state.players.slice(0,11).map((p,i)=>`<button class="pitch-player slot-${i+1}" onclick="playerDetails(${p.id})"><span>${p.ovr}</span><b>${p.name.split(' ').slice(-1)[0]}</b><small>${p.pos}</small></button>`).join('')}</div></div><div class="pitch-legend"><span><i class="legend-green"></i> Titular</span><span>Toque em um atleta para ver detalhes</span></div></section><aside class="tactic-side"><section class="panel"><div class="section-title"><div><h3>Mentalidade</h3><p>Estilo da equipe</p></div></div><div class="mentality-options">${['Defensiva','Equilibrada','Ofensiva','Pressão alta'].map(m=>`<button class="mentality ${state.mentality===m?'active':''}" onclick="state.mentality='${m}';save();renderTactics()"><span>${m==='Defensiva'?'◀':m==='Ofensiva'?'▶':m==='Pressão alta'?'⌁':'◆'}</span>${m}<i>${state.mentality===m?'✓':''}</i></button>`).join('')}</div></section><section class="panel tactic-rating"><div class="section-title"><div><h3>Força do time</h3><p>Onze inicial</p></div></div><div class="rating-number">${Math.round(state.players.slice(0,11).reduce((a,p)=>a+p.ovr,0)/11)}<small>GER</small></div><div class="attribute"><span>Ataque</span><b>70</b><i><em style="width:70%"></em></i></div><div class="attribute"><span>Meio-campo</span><b>68</b><i><em style="width:68%"></em></i></div><div class="attribute"><span>Defesa</span><b>65</b><i><em style="width:65%"></em></i></div></section></aside></div>`;}
function renderMarket(){$('#view-mercado').innerHTML=`<div class="page-heading"><div><div class="eyebrow">DIRETORIA · JANELA ABERTA</div><h1>Mercado da bola</h1><p>Reforce o elenco sem perder o controle das finanças.</p></div><button class="btn btn-secondary" onclick="showToast('Janela de transferências aberta até 31 de julho')">◷ <span>Janela aberta</span></button></div><div class="market-banner"><div><span class="hero-kicker"><i></i> RELATÓRIO DA DIRETORIA</span><h2>Precisamos de mais opções no meio-campo.</h2><p>O orçamento disponível é de ${money(state.money)}.</p></div><span class="market-icon">⇄</span></div><section class="panel market-panel"><div class="section-title"><div><h3>Jogadores disponíveis</h3><p>Atletas livres para negociação</p></div><span class="form-badge">${marketPlayers().length} disponíveis</span></div><div class="market-list">${marketPlayers().map(p=>`<div class="market-row"><span class="player-avatar">${p.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><div class="player-info"><b>${p.name}</b><small>${p.pos} · ${p.age} anos · Livre</small></div><b class="ovr">${p.ovr}</b><div class="market-value"><b>${money(p.value)}</b><small>passe</small></div><button class="btn btn-primary btn-small" onclick="signPlayer(${p.id})" ${state.money<p.value||state.players.length>=28?'disabled':''}>Contratar</button></div>`).join('')}</div></section><p class="market-footnote">A contratação exige pagamento do valor do passe e adiciona o salário à folha semanal. Limite do elenco: 28 atletas.</p>`;}
let prospects=[{name:'Eduardo Ramos',pos:'MC',ovr:66,age:22,value:340000,wage:72000},{name:'Matheus Freitas',pos:'ZAG',ovr:65,age:24,value:290000,wage:65000},{name:'Alan Patrick',pos:'CA',ovr:68,age:26,value:430000,wage:88000},{name:'Riquelme Santos',pos:'LE',ovr:62,age:20,value:250000,wage:52000}].map((p,i)=>({...p,id:100+i,condition:94,morale:75,attrs:{Passe:p.ovr,Finalização:p.ovr-3,Marcação:p.ovr-1,Resistência:p.ovr+2}}));
function marketPlayers(){return prospects.filter(p=>!state.players.some(x=>x.id===p.id));}
function signPlayer(id){const p=prospects.find(x=>x.id===id);if(!p||state.players.length>=28||state.money<p.value){showToast('Não há orçamento ou vaga suficiente para contratar.');return}state.money-=p.value;state.players.push({...p});save();showToast(`${p.name} assinou com o Atlético do Vale!`);renderMarket();}

