function signPlayer(id){const p=prospects.find(x=>x.id===id);if(!p||state.players.length>=28||state.money<p.value){showToast('Não há orçamento ou vaga suficiente para contratar.');return}state.money-=p.value;state.players.push({...p});save();showToast(`${p.name} assinou com o Atlético do Vale!`);renderMarket();}
function applyTraining(playerId=null){if(state.trainingApplied){showToast('O treino de hoje já foi realizado.');return}const training=state.training;const target=playerId?state.players.filter(p=>p.id===playerId):state.players.slice(0,11);if(training==='Recuperação'){target.forEach(p=>{p.condition=Math.min(100,p.condition+14);p.morale=Math.min(100,p.morale+2)});if(!playerId)state.players.slice(11).forEach(p=>p.condition=Math.min(100,p.condition+8));showToast('Boa recuperação. O grupo recuperou condição física.')}else{target.forEach(p=>{p.condition=Math.max(45,p.condition-(training==='Condicionamento'?5:8));p.morale=Math.min(100,p.morale+1);if(Math.random()<.35){const key=training==='Finalização'?'Finalização':training==='Defesa'?'Marcação':training==='Posse de bola'?'Passe':'Resistência';p.attrs[key]=Math.min(95,p.attrs[key]+1);p.ovr=Math.min(90,p.ovr+(p.attrs[key]%3===0?1:0));}});if(!playerId)state.players.slice(11).forEach(p=>p.condition=Math.max(50,p.condition-3));showToast(`Treino de ${training.toLowerCase()} concluído. Bom trabalho!`)}state.trainingApplied=true;save();renderView();}
function advanceDay(){if(dateObj().getDay()===0&&!state.playedToday){showToast('Dia de jogo! Entre em campo antes de avançar.');return}const wasSunday=dateObj().getDay()===0;const d=dateObj();d.setDate(d.getDate()+1);state.day=d.getDate();state.month=d.getMonth()+1;state.year=d.getFullYear();state.playedToday=false;state.trainingApplied=false;state.players.forEach(p=>{p.condition=Math.min(100,p.condition+4+Math.floor(Math.random()*4));p.morale=Math.min(100,p.morale+(p.condition>80?1:0))});if(d.getDay()===1){const wages=state.players.reduce((a,p)=>a+p.wage,0);state.money-=wages;showToast(`Nova semana. Folha salarial paga: ${money(wages)}.`)}else if(wasSunday){showToast('Nova semana de trabalho. Consulte a comissão técnica.')}else showToast('Novo dia, novas oportunidades.');save();renderView();}
function poisson(lambda){const limit=Math.exp(-lambda);let k=0,prod=1;do{k++;prod*=Math.random()}while(prod>limit&&k<8);return k-1;}
function playMatch(){if(dateObj().getDay()!==0||state.playedToday){showToast('A próxima partida acontece no domingo.');return}const opponent=opponentForRound();const team=state.players.slice(0,11);const form=team.reduce((a,p)=>a+p.ovr*(p.condition/100)*(0.8+p.morale/500),0)/11;const diff=form-68;let attackMod=0,defMod=0;if(state.mentality==='Ofensiva')attackMod=.35;if(state.mentality==='Pressão alta'){attackMod=.48;defMod=-.18}if(state.mentality==='Defensiva'){attackMod=-.25;defMod=.3}const homeGoals=poisson(Math.max(.45,1.35+diff*.075+attackMod));const awayGoals=poisson(Math.max(.35,1.02-diff*.035-defMod));const goalNames=team.filter(p=>['CA','PD','PE','MC'].includes(p.pos));const events=[];for(let i=0;i<homeGoals;i++){const scorer=goalNames[Math.floor(Math.random()*goalNames.length)];events.push({minute:Math.floor(8+Math.random()*83),text:`${scorer.name} marca para o Atlético do Vale`,kind:'goal'})}for(let i=0;i<awayGoals;i++)events.push({minute:Math.floor(8+Math.random()*83),text:`Gol do ${opponent}`,kind:'opponent'});events.sort((a,b)=>a.minute-b.minute);events.push({minute:90,text:'Fim de jogo. O árbitro apita pela última vez.',kind:'end'});const won=homeGoals>awayGoals,draw=homeGoals===awayGoals;const reward=won?260000:draw?190000:145000;const gate=Math.round(6500*(18+Math.floor(Math.random()*10)));state.money+=reward+gate;state.played++;state.matchNo++;state.playedToday=true;state.goalsFor+=homeGoals;state.goalsAgainst+=awayGoals;if(won){state.wins++;state.points+=3;state.lastResult='V '+homeGoals+'–'+awayGoals;team.forEach(p=>p.morale=Math.min(100,p.morale+6))}else if(draw){state.draws++;state.points++;state.lastResult='E '+homeGoals+'–'+awayGoals;team.forEach(p=>p.morale=Math.min(100,p.morale+2))}else{state.losses++;state.lastResult='D '+homeGoals+'–'+awayGoals;team.forEach(p=>p.morale=Math.max(35,p.morale-5))}team.forEach(p=>p.condition=Math.max(45,p.condition-10-Math.floor(Math.random()*5)));state.history.unshift({opponent,result:`${homeGoals}–${awayGoals}`,kind:won?'win':draw?'draw':'loss'});state.history=state.history.slice(0,5);const own=state.standings.find(x=>x.name===CLUB);own.p=state.points;own.gp=state.played;const opp=state.standings.find(x=>x.name===opponent);if(opp){opp.gp++;if(awayGoals>homeGoals)opp.p+=3;else if(homeGoals===awayGoals)opp.p++}state.standings.sort((a,b)=>b.p-a.p);save();const resultText=won?'VITÓRIA! Três pontos importantes.':draw?'Empate. Um ponto somado na tabela.':'Derrota. Hora de reagrupar e trabalhar.';openModal('Apito final',`<div class="match-banner"><div class="eyebrow">SÉRIE C · RODADA ${state.matchNo-1}</div><div class="match-score"><div class="match-team"><b>AV</b>Atlético do Vale</div><div class="score">${homeGoals} : ${awayGoals}</div><div class="match-team"><b>${opponent.split(' ').map(x=>x[0]).slice(0,2).join('')}</b>${opponent}</div></div><div class="result-text">${resultText}</div></div><div class="match-events">${events.map(e=>`<div class="event-line"><span>${e.kind==='goal'?'⚽':e.kind==='opponent'?'⚽':'⏱'} &nbsp;${e.text}</span><b>${e.minute}'</b></div>`).join('')}</div><div class="tactic-stat"><span>Premiação + bilheteria</span><b class="money-positive">+ ${money(reward+gate)}</b></div><div class="tactic-stat last"><span>Caixa do clube</span><b>${money(state.money)}</b></div>`,`<button class="btn btn-primary" onclick="closeModal();renderView()">Continuar</button>`);}
function resetGame(){if(confirm('Apagar o progresso e começar uma nova carreira?')){localStorage.removeItem(SAVE_KEY);location.reload()}}
$$('[data-view]').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.view)));
$('#sound-toggle').addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent==='♬'?'♪':'♬';showToast('Som ambiente indisponível neste protótipo')});
updateHeader();renderView();

